//! `Terraria.ID.ItemID` — the full 6196-id item registry. The per-id data is
//! GENERATED by `tools/GenItemData` from the decompiled `Item.cs`
//! (`SetDefaults` stock + case bodies + epilogue) into `itemdata.rs`; this
//! module is the hand-written accessor surface over it (M3-ITEM-1).
//!
//! Inventory slots store the vanilla `ItemID`; the old ad-hoc encoding (tile kind,
//! `WALL_ITEM_BASE`, `WEAPON_ITEM_BASE`, `COIN_ITEM_BASE`) is migrated on load.

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum DamageClass {
    #[default]
    None,
    Melee,
    Ranged,
    Magic,
    Summon,
    Thrown,
}

pub use crate::itemdata::ItemDef;
use crate::itemdata::ITEMS;

pub const COIN_VALUES: [u64; 4] = [1, 100, 10_000, 1_000_000];

/// The hand-written corrections of the GenItemData placeholder band
/// (items 3263-3989): the M6-SAVE-1 merge regenerated `itemdata.rs` and
/// fixed the band's rows (the Amber Staff 3377 / Spirit Flame 3779 / Sky
/// Fracture 3787 now ride the generated rows). The 6171 row is still the
/// band's zero row (the generator misses it): the Bejeweled Staff's C#
/// case (`Item.cs:47550-47555`) transcribed over the `ResetStats` stock -
/// the item the gem-staff shoot's AllGems gate reads (`Player.cs:49262`,
/// `PackGemStaffFeatures`'s `HeldItem.type == 6171`), so the branch is
/// live in the game rather than a test shape.
static ITEM_CORRECTIONS: [ItemDef; 1] = [
    ItemDef {
        id: 6171,
            name: "Bejeweled Staff",
            max_stack: 1,
            tile: None,
            place_style: 0,
            wall: None,
            projectile: Some(126),
            damage: 27,
            rare: 5,
            use_time: 22,
            use_animation: 22,
            use_style: 5,
            hold_style: 0,
            auto_reuse: true,
            head_slot: -1,
            body_slot: -1,
            leg_slot: -1,
            defense: 0,
            life_regen: 0,
            class: DamageClass::Magic,
            crit: 0,
            value: 50000,
            knock_back: 6.0,
            mana: 15,
            use_ammo: 0,
            ammo: 0,
            channel: false,
            reuse_delay: 0,
            consumable: false,
            use_turn: false,
            buff_type: 0,
            buff_time: 0,
            shoot_speed: 6.0,
            width: 40,
            height: 40,
            material: false,
            potion: false,
            heal_life: 0,
            heal_mana: 0,
            scale: 1.0,
            stack: 1,
            bait: 0,
            tile_boost: 0,
            pick: 0,
            axe: 0,
            hammer: 0,
            accessory: false,
            melee: false,
            ranged: false,
            magic: true,
            summon: false,
            thrown: false,
            vanity: false,
            mech: false,
            quest_item: false,
            make_npc: 0,
            fishing_pole: 0,
            hair_dye: -1,
            dye: 0,
            mount_type: -1,
            paint: 0,
            paint_coating: 0,
        },
];

/// The kind's defaults with the [`ITEM_CORRECTIONS`] overrides applied —
/// the single seam every read of the generated table goes through (M4-PROJ-6
/// Phase 2: `prefixed_stats` and every `registry` accessor route here).
pub fn item(id: u16) -> Option<&'static ItemDef> {
    if let Some(d) = ITEM_CORRECTIONS.iter().find(|d| d.id == id) {
        return Some(d);
    }
    ITEMS.iter().find(|d| d.id == id)
}

pub fn get(id: u16) -> Option<&'static ItemDef> {
    item(id)
}

/// `Item.makeNPC` (`Item.cs`'s per-item field) — the item's critter/bait
/// NPC id, the shimmer release arm's input (`WorldItem.GetShimmered`'s
/// makeNPC arm, `WorldItem.cs:1747-1772`). The generated item data does not
/// carry the field yet (a `tools/GenItemData` follow-up), so every kind maps to
/// 0 (no release) until it lands — the release arm's mechanism, the
/// `ShimmerTransformToNPC` override and the ≤50-attempt budget are ported and
/// unit-tested without it.
pub fn make_npc(_id: u16) -> u16 {
    0
}

pub fn name(id: u16) -> &'static str {
    get(id).map_or("Item", |d| d.name)
}

pub fn max_stack(id: u16) -> u32 {
    get(id).map_or(9999, |d| d.max_stack)
}

/// Item dropped by breaking `tile` (`WorldGen.KillTile` drops dirt for grass).
/// Multi-tile objects drop through the kill cascade's object record; the
/// per-kind mapping below is the style-0 slice of the vanilla drop tables
/// (`GetDoorItem`/`GetItemDrop_Tables`/`GetItemDrop_Chair`/
/// `GetItemDrop_Workbenches`/`GetItemDrop_Chests`) — for 10/14/15/18/21 it
/// equals `by_tile` (the placing item), and the open door (11, which no item
/// places) drops the closed-door item (`GetDoorItem(0)` = 25).
///
/// `frame_y` feeds the planter-box drop `3215 + frameY / 18`
/// (`KillTile_GetItemDrops`, `WorldGen.cs:65211-65213`); record/interaction
/// call sites pass 0 (tile 380 never dies through a `Check*` record — the
/// inline merge block `WorldGen.cs:85296-85367` never kills it).
pub fn tile_drop(tile: u16, frame_y: i16) -> Option<u16> {
    match tile {
        2 => Some(2),
        11 => Some(25),
        // The world cactus 80 drops the Cactus item even though the item
        // places the CactusBlock 188, not 80 (`KillTile_GetItemDrops`,
        // `WorldGen.cs:64717-64720`: `case 80`/`case 188` both → 276) — the
        // generated item table only carries the 276→188 placement, so the
        // reverse `by_tile` lookup misses 80.
        80 => Some(276),
        // `case 78: dropItem = 222;` (`WorldGen.cs:64711-64713`).
        78 => Some(222),
        // `case 380: dropItem = 3215 + tileCache.frameY / 18;` (:65211-65213).
        380 => Some((3215 + i32::from(frame_y) / 18) as u16),
        // The sunflower's per-cell case is in the empty group (:65759+); 63 is
        // what the cascade's `CheckSunflower` record spawns
        // (`Item.NewItem(…, 63)`, `WorldGen.cs:53787-53791`).
        27 => Some(63),
        // The loot pot / herbs / piles drop nothing per-cell (the empty case
        // group `WorldGen.cs:65759-65815` — 28, 82, 185, 186, 187); the pot's
        // loot is `SpawnThingsFromPot` (:57011-57014), the herbs' rolls ride
        // the RNG resolver (:65674-65698) and 187's sword-in-stone special
        // rides the `Check3x2` pile event (:49828-49839) — all app-side.
        // Without these arms the `by_tile` fallback leaks the seed item 307
        // for tile 82.
        28 | 82 | 83 | 84 | 185 | 186 | 187 => None,
        // The tree trunks (5/596/616/634) and the palm (323) — their drop is
        // the `KillTile_GetTreeDrops` record (the wood of the tree's family,
        // `WorldGen.cs:66189-66261`), which the kill cascade emits per cell;
        // the generic `by_tile` fallback finds no placing item for them.
        5 | 323 | 596 | 616 | 634 => None,
        // The demon/crimson altar (`KillTile_GetItemDrops`'s empty case 26
        // group, `WorldGen.cs:65758` → `:66090`): the altar is destroyed, not
        // dropped — the `by_tile` fallback would leak the Journey-mode item
        // 5532 "Demon Altar". The ore seeding rides `SmashAltar` instead.
        26 => None,
        _ => by_tile(tile),
    }
}

/// Item that places `tile`, if the registry has one.
pub fn by_tile(tile: u16) -> Option<u16> {
    ITEMS.iter().find(|d| d.tile == Some(tile)).map(|d| d.id)
}

/// Item that places `wall`, if the registry has one.
pub fn by_wall(wall: u16) -> Option<u16> {
    ITEMS.iter().find(|d| d.wall == Some(wall)).map(|d| d.id)
}

pub fn place_tile(id: u16) -> Option<u16> {
    // `Item.cs:33745-33754` (case 3813): `createTile = 463`. The generated
    // `itemdata.rs` row carries `tile: None` for the Defender's Forge (the
    // GenItemData dispatcher mis-merged the case — the generator bug rides
    // here until the regen pass; the M3-EQUIP-3 `accessory_life_regen`
    // precedent).
    if id == 3813 {
        return Some(463);
    }
    get(id)?.tile
}

/// `Item.placeStyle` (`Item.cs:173`, field default 0).
pub fn place_style(id: u16) -> i32 {
    get(id).map_or(0, |d| d.place_style)
}

pub fn place_wall(id: u16) -> Option<u16> {
    get(id)?.wall
}

pub fn damage(id: u16) -> i32 {
    get(id).map_or(0, |d| d.damage)
}

/// `Item.rare` (`Item.cs`), used by `Main.MouseText_DrawItemTooltip_GetItemNameColor`.
pub fn rare(id: u16) -> i32 {
    get(id).map_or(0, |d| d.rare)
}

pub fn projectile(id: u16) -> Option<u16> {
    get(id)?.projectile
}

pub fn is_weapon(id: u16) -> bool {
    get(id).is_some_and(|d| d.projectile.is_some())
}

pub fn is_coin(id: u16) -> bool {
    (71..=74).contains(&id)
}

pub fn coin_index(id: u16) -> Option<usize> {
    is_coin(id).then(|| (id - 71) as usize)
}

pub fn coin_value(id: u16) -> u64 {
    coin_index(id)
        .and_then(|i| COIN_VALUES.get(i))
        .copied()
        .unwrap_or(0)
}

/// Coin item id for a denomination (0 copper .. 3 platinum).
pub fn coin_id(denom: usize) -> u16 {
    71 + denom.min(3) as u16
}

/// `Item.netDefaults` negative id → the real id it materializes
/// (`Item.cs:1211-1367`: −1..−48 map to coins/picks/axes; anything else falls
/// back to 0).
pub fn net_default(negative: i16) -> u16 {
    crate::itemdata::NEGATIVE_DEFAULTS
        .iter()
        .find(|(n, _)| *n == negative)
        .map_or(0, |(_, id)| *id)
}

/// `Item.OnCreated` re-defaults (`Item.cs:48936-48942`): crafting id A
/// materializes as id B (5437 → 5358).
pub fn on_created(id: u16) -> Option<u16> {
    crate::itemdata::ON_CREATED
        .iter()
        .find(|(a, _)| *a == id)
        .map(|(_, b)| *b)
}

/// Version-2 saves stored wall kinds by the old port's numbering; the two
/// walls it modelled were stone (1) and dirt (2) — mapped to the items the
/// old registry defined for them (26/30).
fn legacy_wall_item(kind: u16) -> u16 {
    match kind {
        1 => 26,
        2 => 30,
        _ => 0,
    }
}

/// Migrates a version-1/2 slot kind (tile kind, wall/weapon/coin ranges) to `ItemID`.
pub fn migrate_kind(old: u16) -> u16 {
    match old {
        0..=999 => by_tile(old).unwrap_or(0),
        10_000..=19_999 => legacy_wall_item(old - 10_000),
        20_000..=29_999 => 42,
        _ => coin_id((old - 30_000) as usize),
    }
}

#[cfg(test)]
mod tests {
    #![allow(non_snake_case)] // DW-IDs are part of the test names (traceability)
    use super::*;

    #[test]
    fn use_timings_match_item_setdefaults() {
        // Item.cs SetDefaults1: every ported kind swings with useStyle 1 over
        // 15 ticks; blocks take 10 ticks of useTime, the grass seeds 7, the
        // shuriken 15 with autoReuse off.
        for id in [2, 3, 8, 9, 11, 12, 13, 14, 169, 172, 174, 276, 593] {
            let d = get(id).unwrap_or_else(|| panic!("id {id}"));
            assert_eq!(
                (d.use_time, d.use_animation, d.use_style),
                (10, 15, 1),
                "id {id}"
            );
            assert!(d.auto_reuse, "id {id}");
        }
        for id in [26, 30] {
            let d = get(id).unwrap();
            assert_eq!(
                (d.use_time, d.use_animation, d.use_style),
                (7, 15, 1),
                "id {id}"
            );
        }
        let shuriken = get(42).unwrap();
        assert_eq!((shuriken.use_time, shuriken.use_animation), (15, 15));
        assert!(!shuriken.auto_reuse, "the shuriken does not auto-repeat");
        // The torch is the one holdStyle-1 item of the set.
        let torch = get(8).unwrap();
        assert_eq!((torch.hold_style, torch.use_style), (1, 1));
    }

    #[test]
    fn unregistered_kinds_fall_back_to_the_vanilla_default() {
        assert!((crate::item::use_animation_secs(9999) - 0.25).abs() < 1e-6);
        assert_eq!(crate::item::hold_style(9999), 0);
        assert!((crate::item::use_animation_secs(8) - 0.25).abs() < 1e-6);
    }

    #[test]
    fn test_DW_2_2_wooden_set_item_data_matches_item_cs() {
        // (id, createTile, autoReuse) — `Item.cs:1677-1687` (WoodenDoor, the
        // one placement without `autoReuse`), `:1758-1768` (WoodenTable),
        // `:1784-1794` (WoodenChair), `:1958-1968` (Chest), `:1806-1816`
        // (WorkBench). Every SetDefaults case leaves `placeStyle` unset → 0,
        // and `maxStack` stays `Item.CommonMaxStack` (9999 — the 1.4.5 stack
        // raise, `Item.cs:49017` + `:49966`).
        let cases = [
            (25u16, 10u16, false),
            (32, 14, true),
            (34, 15, true),
            (48, 21, true),
            (36, 18, true),
        ];
        for (id, tile, auto_reuse) in cases {
            let d = get(id).unwrap_or_else(|| panic!("item {id} missing"));
            assert_eq!(d.tile, Some(tile), "id {id}");
            assert_eq!(d.place_style, 0, "id {id}");
            assert_eq!(
                (d.use_time, d.use_animation, d.use_style),
                (10, 15, 1),
                "id {id}"
            );
            assert_eq!(d.auto_reuse, auto_reuse, "id {id}");
            assert_eq!(d.max_stack, 9999, "id {id}");
        }
        // The item↔tile mapping is bidirectional where the set is complete.
        assert_eq!(by_tile(10), Some(25));
        assert_eq!(by_tile(14), Some(32));
        assert_eq!(by_tile(15), Some(34));
        assert_eq!(by_tile(21), Some(48));
        assert_eq!(place_style(9999), 0, "unknown items default to style 0");
    }

    #[test]
    fn test_dw_2_2_generated_rows_match_item_cs_spots() {
        // One spot per SetDefaults range + the epilogue rules, all cited:
        // shuriken 42 (`Item.cs:1869-1890`: shoot 3, damage 10, no autoReuse);
        // Flower of Fire 112 (`:2710-2723`: damage 48, mana 9, rare 3, value
        // hellPrice = sellPrice(0,2,50) = 125000 with the ×5 factor of
        // `Item.cs:49422-49426`); iron bow 99 (style 5, useAmmo Arrow = 40);
        // the bait-50 critter 1999 (case num 5 → bait 50, `Item.cs:21330+`,
        // then the bait ladder rare 3, `Item.cs:48838-48847`); the golf ball
        // 4251 (SD5); dirt 2 at CommonMaxStack 9999 (`Item.cs:49966`).
        let shuriken = get(42).unwrap();
        assert_eq!((shuriken.projectile, shuriken.damage), (Some(3), 10));
        assert!(!shuriken.auto_reuse);
        let flower = get(112).unwrap();
        assert_eq!((flower.damage, flower.mana, flower.rare, flower.value),
            (48, 9, 3, 125000));
        assert!(matches!(flower.class, DamageClass::Magic));
        let bow = get(99).unwrap();
        assert_eq!((bow.use_style, bow.use_ammo), (5, 40));
        let critter = get(1999).unwrap();
        assert_eq!((critter.bait, critter.rare), (50, 3));
        let golf = get(4251).unwrap();
        assert_eq!((golf.projectile, golf.rare, golf.value), (Some(748), 2, 10000));
        // SD4 range: Architect Gizmo Pack 3061 (Item.cs:27677-27683)
        let gizmo = get(3061).unwrap();
        assert_eq!((gizmo.rare, gizmo.value), (5, 200000));
        assert!(gizmo.accessory);
        assert_eq!(get(2).unwrap().max_stack, 9999);
        // Slots are i16 with −1 = none; slot 0 is REAL (the Familiar set,
        // ids 269-271, `Item.cs` case 269/270/271 headSlot/bodySlot/legSlot 0).
        assert_eq!(get(271).unwrap().head_slot, 0);
        assert_eq!(get(1).unwrap().head_slot, -1);
    }

    #[test]
    fn test_dw_2_2_net_defaults_and_on_created() {
        // `Item.cs:1211-1367`: −1 → 3521 (copper coin), −48 → 3480; anything
        // outside the table falls back to 0. `Item.cs:48936-48942`: 5437 → 5358.
        assert_eq!(net_default(-1), 3521);
        assert_eq!(net_default(-48), 3480);
        assert_eq!(net_default(0), 0);
        assert_eq!(net_default(-49), 0);
        assert_eq!(on_created(5437), Some(5358));
        assert_eq!(on_created(42), None);
    }

    #[test]
    fn test_dw_2_3_out_of_range_fallbacks_unchanged() {
        // Ids beyond ItemID.Count (6196) hit the accessors' fallbacks —
        // byte-identical to the pre-M3-ITEM-1 behaviour. Id 0 is a REAL row
        // now (SetDefaults(0): name "None", stock, stack 0 — Item.cs:48685).
        assert_eq!(name(6196), "Item");
        assert_eq!(max_stack(6196), 9999);
        assert_eq!(crate::item::hold_style(6196), 0);
        assert!((crate::item::use_animation_secs(6196) - 0.25).abs() < 1e-6);
        assert_eq!(place_style(6196), 0);
        // id 0 is the faithful row: SetDefaults(0) leaves stack 0
        // (Item.cs:48685-48688)
        assert_eq!(name(0), "None");
        assert_eq!(get(0).unwrap().stack, 0);
    }

    #[test]
    fn test_DW_3_2_tile_drop_wooden_set() {
        // The kill-cascade drop mapping — the style-0 slice of the vanilla
        // drop tables: `GetDoorItem(0)` = 25 (`WorldGen.cs:69200-69204`),
        // `GetItemDrop_Tables(0)` = 32 (:42194), `GetItemDrop_Chair(0)` = 34
        // (:42635), `GetItemDrop_Workbenches(0)` = 36 (:42447),
        // `GetItemDrop_Chests(0, false)` = 48 (:41677-41681). The open door
        // (11) has no placing item and needs the explicit row — it drops the
        // closed-door item (`CheckDoorOpen` → `DropDoorItem` :86415).
        assert_eq!(tile_drop(10, 0), Some(25));
        assert_eq!(tile_drop(11, 0), Some(25));
        assert_eq!(tile_drop(14, 0), Some(32));
        assert_eq!(tile_drop(15, 0), Some(34));
        assert_eq!(tile_drop(18, 0), Some(36));
        assert_eq!(tile_drop(21, 0), Some(48));
        // Non-object kinds keep their existing rows.
        assert_eq!(tile_drop(2, 0), Some(2), "grass drops dirt");
        assert_eq!(tile_drop(1, 0), Some(3), "stone drops via its item");
    }

    // DW-3.1: the phase-3 tile_drop rows (`KillTile_GetItemDrops`).
    #[test]
    fn test_DW_3_1_tile_drop_map() {
        // `case 78: dropItem = 222;` (`WorldGen.cs:64711-64713`).
        assert_eq!(tile_drop(78, 0), Some(222));
        // `case 380: dropItem = 3215 + tileCache.frameY / 18;` (:65211-65213) —
        // the style rows 0..7 of the planter boxes.
        for style in 0..8 {
            assert_eq!(tile_drop(380, (18 * style) as i16), Some((3215 + style) as u16), "style {style}");
        }
        // The sunflower's item is the cascade record's (CheckSunflower's
        // `Item.NewItem(…, 63)`, :53787-53791).
        assert_eq!(tile_drop(27, 0), Some(63));
        // The empty per-cell case group (:65759-65815): 28/82/185/186/187 and
        // the herb stages (their rolls ride the RNG resolver) drop nothing —
        // and the `by_tile` fallback no longer leaks the seed 307 for 82.
        for tile in [28, 82, 83, 84, 185, 186, 187] {
            assert_eq!(tile_drop(tile, 0), None, "tile {tile}");
        }
        assert_eq!(tile_drop(82, 0), None, "by_tile(82) must not yield 307");
        assert_eq!(by_tile(82), Some(307), "the fallback itself is intact");
    }

    // DW-2.3: the M4-PROJ-6 corrections of the GenItemData placeholder band.
    #[test]
    fn test_DW_2_3_the_corrected_staff_rows_answer_the_item_cs_values() {
        // `registry::item` — the Amber Staff, `Item.cs:30858-30875`.
        let amber = item(3377).unwrap();
        assert_eq!((amber.damage, amber.mana), (21, 9));
        assert_eq!(amber.class, DamageClass::Magic);
        assert_eq!(amber.projectile, Some(597));
        assert_eq!((amber.use_time, amber.use_animation, amber.use_style), (28, 28, 5));
        assert_eq!((amber.shoot_speed, amber.knock_back), (9.0, 4.75));
        assert!(amber.auto_reuse);
        assert!(!amber.channel, "the case body never sets `channel`");
        assert_eq!((amber.rare, amber.value, amber.width, amber.height), (1, 20000, 40, 40));
        // The same row through `registry::get` and its `use_time`.
        assert!(std::ptr::eq(get(3377).unwrap(), amber));
        assert_eq!(get(3377).unwrap().use_time, 28);
        // The accessor surface over the seam.
        assert_eq!(projectile(3377), Some(597));
        assert_eq!(damage(3377), 21);
        assert_eq!(rare(3377), 1);
        assert!(is_weapon(3377));
        // `prefixed_stats` with prefix 0 (the short-circuit branch).
        let s = crate::prefix::prefixed_stats(3377, 0).unwrap();
        assert_eq!((s.damage, s.mana, s.use_time, s.use_animation), (21, 9, 28, 28));
        assert_eq!((s.shoot_speed, s.knock_back, s.rare, s.value), (9.0, 4.75, 1, 20000));
        // The Spirit Flame, `Item.cs:33455-33472` (value = `sellPrice(0,1)`).
        let flame = item(3779).unwrap();
        assert_eq!((flame.damage, flame.mana), (85, 14));
        assert_eq!(flame.class, DamageClass::Magic);
        assert_eq!(flame.projectile, Some(659));
        assert_eq!((flame.use_time, flame.use_animation), (22, 22));
        assert_eq!((flame.shoot_speed, flame.knock_back), (3.0, 5.0));
        assert!(flame.auto_reuse);
        assert_eq!((flame.rare, flame.value, flame.width, flame.height), (4, 50000, 26, 28));
        // The Sky Fracture, `Item.cs:33531-33550`.
        let sky = item(3787).unwrap();
        assert_eq!((sky.damage, sky.mana, sky.crit), (38, 17, 20));
        assert_eq!(sky.class, DamageClass::Magic);
        assert_eq!(sky.projectile, Some(660));
        assert_eq!((sky.use_time, sky.use_animation, sky.reuse_delay), (4, 12, 18));
        assert_eq!((sky.shoot_speed, sky.knock_back), (8.75, 6.0));
        assert!(sky.auto_reuse);
        assert_eq!((sky.rare, sky.value, sky.width, sky.height), (4, 300000, 16, 16));
        let s = crate::prefix::prefixed_stats(3787, 0).unwrap();
        assert_eq!((s.damage, s.mana), (38, 17));
        assert_eq!((s.use_time, s.use_animation, s.reuse_delay), (4, 12, 18));
        // An unregistered kind keeps the `None`.
        assert!(item(7000).is_none());
    }

    #[test]
    fn test_DW_2_3_a_prefixed_staff_rides_the_corrected_base() {
        // The Mystic prefix (26, `PREFIXES_FOR_MAGIC`'s head — `Item.cs`'s
        // switch: damage x1.1, manaCost x0.85) multiplies the CORRECTED base:
        // 21 -> 23 (the placeholder's 15 would give 16), mana 9 -> 8 (the
        // placeholder's 0 stays 0).
        let s = crate::prefix::prefixed_stats(3377, 26).unwrap();
        assert_eq!(s.damage, 23);
        assert_eq!(s.mana, 8);
        assert_eq!(s.use_time, 28, "the speed multiplier is 1");
        assert_eq!(s.shoot_speed, 9.0);
    }

    #[test]
    fn test_DW_2_3_the_placeholder_band_neighbours_stay_untouched() {
        // The correction is one seam over three ids: every other row of the
        // 3263-3989 placeholder band still reads the generated row verbatim.
        // The M6-SAVE-1 merge regenerated `itemdata.rs`, so the placeholder
        // band reads its generated rows: the three staves answer their
        // `Item.cs` values from the generated table (their own tests pin the
        // values), and only 6171 rides the correction.
        for id in [3376u16, 3378, 3778, 3780, 3786, 3788] {
            let got = item(id).unwrap();
            assert!(std::ptr::eq(got, &ITEMS[id as usize]), "id {id} must not be shadowed");
        }
        // The full-table sweep: only 6171 rides the corrections, and the
        // corrected row is not the generated one.
        for id in 0..ITEMS.len() as u16 {
            let got = item(id).unwrap();
            match ITEM_CORRECTIONS.iter().find(|d| d.id == id) {
                Some(want) => assert!(std::ptr::eq(got, want), "id {id} must ride the correction"),
                None => assert!(
                    std::ptr::eq(got, &ITEMS[id as usize]),
                    "id {id} must keep its generated row"
                ),
            }
        }
        assert!(!std::ptr::eq(item(6171).unwrap(), &ITEMS[6171]));
    }
}
